"""Builds the GitHub Pages site in docs/ from the pages generated by the CAD and electronics scripts.

    python3 tools/build_site.py            # copies the current pages
    python3 tools/build_site.py --preview  # also renders docs/assets/preview.png (needs Playwright)

Before running it, regenerate what changed:
    mechanical/cad/arm_v0:   python3 viewer_build.py        (full rebuild, ~10 min)  or  --tpl (template only)
    electronics:             python3 hand_passive_schematic.py && python3 build_page.py
Set OWNER and REPO below once the GitHub repository exists."""
import os, re, shutil, subprocess, sys

OWNER = 'enricomichelato'                     # GitHub user or organisation
REPO = 'Idra'                       # repository name
REPO_URL = f'https://github.com/{OWNER}/{REPO}'

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DOCS = os.path.join(ROOT, 'docs')
SRC = {
    'index.html': 'mechanical/cad/arm_v0/arm_3d.html',
    'kinematics.html': 'control/kinematics_explainer.html',
}
LINKS = [('./', 'Simulator'), ('kinematics.html', 'Kinematics'), (REPO_URL, 'Repository')]


HERO = """<p class="lede">A six-axis desk arm whose hand can spin forever: the wrist roll has no end stop and never has to unwind.</p>"""

SECTIONS = """<section class="feat" aria-label="What makes it different">
<article><h3>Endless roll</h3><p>The hand turns without limit, in either direction. The roll joint has no end stop, so the arm never has to stop and unwind in the middle of a task.</p></article>
<article><h3>Two motors per joint</h3><p>Elbow and wrist are bevel differentials driven by two belts: motors turning together bend the joint, turning against each other they rotate it. The shoulder has two motors too, one on each bone, on teeth cut in the steel bones.</p></article>
<article><h3>Built to hold 1 kg</h3><p>Steel planetary gearboxes at base and shoulder, two belt stages at the elbow, steel gear teeth at the shoulder, waterjet-cut steel bones, springs that balance the arm. Every motor stays well under half of its torque with 1 kg on the wrist (model estimate).</p></article>
</section>
<div class="cols">
<section class="panel"><h2>Numbers</h2>
<table class="spec"><tbody>
<tr><td>Axes</td><td>6 + three-finger gripper</td></tr>
<tr><td>Reach</td><td>680 mm to the grip centre; picks on the desk up to about 48 cm away</td></tr>
<tr><td>Payload</td><td>1 kg at the wrist</td></tr>
<tr><td>Grip</td><td>about 18 N per finger, holds with the power off</td></tr>
<tr><td>Sag under 500 g</td><td>about 1.2 mm at full reach (estimate)</td></tr>
<tr><td>Motors</td><td>2 NEMA23 + 6 NEMA17, steppers; a smart servo in the hand</td></tr>
<tr><td>Structure</td><td>Waterjet-cut steel upper-arm bones (with the shoulder teeth) and shoulder cheeks, printed PETG-CF forearm, truss-slotted bones</td></tr>
<tr><td>Printer bed needed</td><td>256 x 256 mm</td></tr>
</tbody></table></section>
<section class="panel"><h2>Status</h2>
<p style="margin:0 0 10px;color:var(--mut);max-width:60ch">IDRA is a design model. Every part is generated by CadQuery scripts and checked for collisions, the motors are sized with a dynamics model, and the print and cutting files are ready. Nothing has been built or tested yet.</p>
<div class="row"><a href="kinematics.html">How the kinematics works</a></div>
<div class="row"><a href="REPO_URL">Source, CAD scripts and build files</a></div>
</section>
</div>
<p class="foot">The simulator runs the same forward and inverse kinematics as the robot code (<code>control/kinematics.py</code>). Model: arm v0.50. © 2026 Enrico Michelato, all rights reserved.</p>"""


def nav(current, style):
    items = ''.join(f'<a href="{h}"{" aria-current=\"page\"" if h.split("#")[0] in (current, "./" if current == "index.html" else "") else ""} '
                    f'style="color:inherit;text-decoration:{"underline" if h.split("#")[0] in (current, "./" if current == "index.html" else "") else "none"}">{t}</a>'
                    for h, t in LINKS)
    return f'<nav aria-label="Project pages" style="{style}">{items}</nav>'


def full_document(body, lang='en'):
    """The artifact pages are written without <html>/<head>: give them a proper document for GitHub Pages."""
    if body.lstrip().lower().startswith('<!doctype'):
        return body
    return ('<!doctype html>\n<html lang="%s"><head><meta charset="utf-8">\n'
            '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n'
            '<style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}'
            'body{margin:0}img{max-width:100%%}[hidden]{display:none!important}</style>\n'
            '</head><body>\n%s\n</body></html>\n') % (lang, body)


def main():
    os.makedirs(os.path.join(DOCS, 'assets'), exist_ok=True)
    for dst, src in SRC.items():
        p = os.path.join(ROOT, src)
        if not os.path.exists(p):
            sys.exit(f'missing {src}: regenerate it first')
        html = open(p, encoding='utf-8').read()
        if dst == 'index.html':
            items = ''.join(f'<a href="{h}"{" aria-current=\"page\"" if h == "./" else ""}>{t}</a>' for h, t in LINKS)
            html = html.replace('<!--SITE_NAV-->', f'<nav class="sitenav" aria-label="Project pages">{items}</nav>')
            html = html.replace('<!--SITE_HERO-->', HERO).replace('<!--SITE_SECTIONS-->', SECTIONS.replace('REPO_URL', REPO_URL))
        else:
            html = full_document(html)
            mw = {'kinematics.html': 1320, 'passive-hand.html': 1000}[dst]       # same width as the page column
            bar = nav(dst, f'display:flex;flex-wrap:wrap;gap:6px 18px;max-width:{mw}px;margin:0 auto;'
                           'padding:12px max(16px,env(safe-area-inset-left,0px)) 0;font:13px/1.4 system-ui,sans-serif;color:var(--muted)')
            html = html.replace('<body>\n', '<body>\n' + bar + '\n', 1)
        open(os.path.join(DOCS, dst), 'w', encoding='utf-8').write(html)
        print(f'docs/{dst}  {len(html)/1e6:.2f} MB')
    open(os.path.join(DOCS, '.nojekyll'), 'w').close()          # serve the files as they are
    if '--preview' in sys.argv:
        subprocess.run(['node', os.path.join(ROOT, 'tools', 'preview.js'), DOCS], check=True)


if __name__ == '__main__':
    main()
